import concurrent.futures,hashlib,json,os,subprocess,sys
from datetime import datetime,timezone
from pathlib import Path
sys.path.insert(0,str(Path.cwd()/'src'))
from proworksim.audit import code_identity
PYTHON=str(Path.cwd()/'.venv/bin/python')
JOBS={'R0':['scripts/evaluation_boundary_experiment.py','--output','runs/evaluation-boundary-v10-stage1','--workers','4'],'R1':['scripts/staff_runtime_experiment.py','--output','runs/staff-runtime-v10-stage1','--workers','4','--groups','R1'],'pytest':['-m','pytest','-q'],'ruff':['-m','ruff','check','src','tests','scripts']}
def now():return datetime.now(timezone.utc).isoformat()
def hashes():
 paths={Path('pyproject.toml')}
 for base in ['tests','scripts','examples/scenarios-v10']:
  paths.update(p for p in Path(base).rglob('*') if p.is_file() and p.suffix in ['.py','.json'])
 return {str(p):hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(paths)}
def job(pair):
 name,args=pair;before=code_identity();start=now();log=Path('/tmp/proworksim-v010-a-'+name+'.log')
 with log.open('w') as out:r=subprocess.run([PYTHON]+args,stdout=out,stderr=subprocess.STDOUT)
 result={'group':name,'command':[PYTHON]+args,'source_before':before,'source_after':code_identity(),'started_at':start,'ended_at':now(),'exit_code':r.returncode,'log':str(log),'log_sha256':hashlib.sha256(log.read_bytes()).hexdigest()}
 print(json.dumps(result),flush=True);return result
before=code_identity();assert before['code_dirty'] is False
inputs=hashes();start=now()
with concurrent.futures.ThreadPoolExecutor(max_workers=4) as pool:jobs=list(pool.map(job,JOBS.items()))
report={'source_before':before,'source_after':code_identity(),'started_at':start,'ended_at':now(),'input_sha256_before':inputs,'input_sha256_after':hashes(),'jobs':jobs,'resources':{'cpu_count':os.cpu_count(),'parallel_jobs':4,'one_writer_per_world':True,'model_calls':0,'GPU_used':False},'scope':'Stage A R0/R1. Prepared scenario/policy code does not establish stage B R2-R4 results.'}
Path('/tmp/proworksim-v010-a-supervisor.json').write_text(json.dumps(report,indent=2)+'\n')
assert report['source_before']==report['source_after'] and inputs==report['input_sha256_after']
raise SystemExit(0 if all(j['exit_code']==0 for j in jobs) else 1)

